import { test, expect } from '@playwright/test';

test.describe('List Item Reordering by Drag and Drop', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/list-items');
  });

  test('should successfully reorder list items using drag and drop', async ({ page }) => {
    // Verify initial list order
    const listItems = page.getByRole('listitem');
    const initialOrder = await listItems.map((item) => item.textContent());
    expect(initialOrder).toEqual(['Item 1', 'Item 2', 'Item 3']);

    // Get the first item and drag it to the end
    const firstItem = page.getByText('Item 1');
    await firstItem.dragTo(page.getByText('Item 3'));

    // Verify the new order
    const reorderedItems = page.getByRole('listitem');
    const finalOrder = await reorderedItems.map((item) => item.textContent());
    expect(finalOrder).toEqual(['Item 2', 'Item 3', 'Item 1']);

    // Verify the reorder button is visible and enabled
    const reorderButton = page.getByRole('button', { name: /reorder/i });
    await expect(reorderButton).toBeVisible();
    await expect(reorderButton).toBeEnabled();

    // Click reorder button to persist changes
    await reorderButton.click();

    // Verify success message appears
    const successMessage = page.getByText('List reordered successfully');
    await expect(successMessage).toBeVisible();

    // Verify the order is persisted after page refresh
    await page.reload();
    const persistedItems = page.getByRole('listitem');
    const persistedOrder = await persistedItems.map((item) => item.textContent());
    expect(persistedOrder).toEqual(['Item 2', 'Item 3', 'Item 1']);
  });

  test('should handle drag and drop with empty list and error states', async ({ page }) => {
    // Navigate to empty list state
    await page.goto('/list-items?empty');

    // Verify empty state message
    const emptyState = page.getByText('No items in the list');
    await expect(emptyState).toBeVisible();

    // Attempt to drag an item (should not be possible)
    const dragHandle = page.getByRole('button', { name: /drag handle/i });
    await expect(dragHandle).not.toBeVisible();

    // Verify reorder button is disabled when list is empty
    const reorderButton = page.getByRole('button', { name: /reorder/i });
    await expect(reorderButton).toBeDisabled();

    // Add items to the list
    const addItemButton = page.getByRole('button', { name: /add item/i });
    await addItemButton.click();
    const newItemInput = page.getByPlaceholder('Enter item name');
    await newItemInput.fill('New Item');
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify new item is added
    const listItems = page.getByRole('listitem');
    const itemText = await listItems.first().textContent();
    expect(itemText).toContain('New Item');

    // Drag and drop the new item
    const newItem = page.getByText('New Item');
    const targetItem = page.getByText('Item 1');
    await newItem.dragTo(targetItem);

    // Verify the new order
    const reorderedItems = page.getByRole('listitem');
    const finalOrder = await reorderedItems.map((item) => item.textContent());
    expect(finalOrder).toEqual(['New Item', 'Item 1']);

    // Verify error handling when dropping outside a valid target
    const dropZone = page.locator('[data-testid="drop-zone"]');
    await dropZone.dragTo(page.getByText('Item 1'));

    // Verify the item remains in its original position
    const finalOrderAfterInvalidDrop = await reorderedItems.map((item) => item.textContent());
    expect(finalOrderAfterInvalidDrop).toEqual(['New Item', 'Item 1']);
  });
});
